--
-- Warlock permanent demons: pet_levelstats for Doomguard (11859) and Infernal (89).
-- Both are now persistent Pets (see SpellInfoCorrections for spells 1122 / 18540), so they need
-- real per-level stats instead of the placeholder `1`s in the base data. Values mirror Felguard (17252).
--

DELETE FROM `pet_levelstats` WHERE `creature_entry` IN (89, 11859);
